20	  const snapshot = snapshotOf([
21	    { id: 'welcome', title: '欢迎', body: 'see [[ghost]] for dangling links', tags: ['Intro', 'intro'] },
22	  ]);
23	  const raw = JSON.stringify(snapshot);
24	  assert.match(raw, /^\{"version":1,"documents":\[\{"id"/u);
25	  assert.match(raw, /\],"checksum":"[0-9a-f]{64}"\}$/u);
26	  assert.deepEqual(Object.keys(snapshot), ['version', 'documents', 'checksum']);
27	  assert.deepEqual(Object.keys(snapshot.documents[0]), ['id', 'title', 'body', 'tags']);
28	  assert.equal(snapshot.version, 1);
29	  assert.equal(snapshot.checksum, canonicalChecksum(snapshot));
30	  assert.equal(snapshot.checksum, snapshot.checksum.toLowerCase());
31	});
