36	    { id: 'a_b', title: 'Underscore', body: 'body text', tags: [] },
37	    { id: 'a.b', title: 'Dot', body: 'body text', tags: [] },
38	  ]);
39	  assert.deepEqual(snapshot.documents.map((document) => document.id), ['a.b', 'a_b']);
40	});
