50	test('exportJSON does not share internal references', () => {
51	  const workspace = new Workspace();
52	  workspace.add({ id: 'note', title: 'Note', body: 'Body', tags: ['tag'] });
53	  const first = workspace.exportJSON();
54	  first.documents[0].title = 'Hijacked';
55	  first.documents[0].tags.push('hijacked');
56	  const second = workspace.exportJSON();
57	  assert.equal(second.documents[0].title, 'Note');
58	  assert.deepEqual(second.documents[0].tags, ['tag']);
59	});
60	
61	test('exportJSON on an empty workspace has a stable checksum', () => {
62	  const snapshot = new Workspace().exportJSON();
63	  assert.deepEqual(snapshot, { version: 1, documents: [], checksum: canonicalChecksum(snapshot) });
64	  assert.deepEqual(new Workspace().exportJSON(), snapshot);
65	});
66	
67	test('importJSON accepts out-of-order documents when the checksum matches', () => {
68	  const original = snapshotOf([
69	    { id: 'a', title: 'A', body: 'a body', tags: [] },
70	    { id: 'b', title: 'B', body: 'b body', tags: ['x'] },
71	  ]);
72	  const shuffled = structuredClone(original);
73	  shuffled.documents.reverse();
74	  const workspace = new Workspace();
75	  const result = workspace.importJSON(shuffled, { mode: 'replace' });
76	  assert.deepEqual(result, original);
77	  assert.deepEqual(workspace.exportJSON(), original);
78	});
79	
80	test('importJSON accepts a JSON string as well as an object', () => {
81	  const snapshot = snapshotOf([{ id: 'a', title: 'A', body: 'body text', tags: [] }]);
82	  const workspace = new Workspace();
83	  workspace.importJSON(JSON.stringify(snapshot), { mode: 'replace' });
84	  assert.deepEqual(workspace.exportJSON(), snapshot);
85	});
86	
87	test('merge keeps existing documents and adds new ones', () => {
88	  const base = snapshotOf([{ id: 'a', title: 'A', body: 'old [[c]]', tags: ['keep'] }]);
89	  const incoming = snapshotOf([
90	    { id: 'b', title: 'B', body: 'links [[a]]', tags: ['new'] },
91	    { id: 'c', title: 'C', body: 'dangling [[nowhere]]', tags: [] },
92	  ]);
93	  const workspace = new Workspace();
